#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd)";source "$SCRIPT_DIR/project_config.sh"
usage(){ echo "Usage: resample_to_rf1_grid.sh --input FILE --kind bold|mask --output FILE [--overwrite]" >&2; }
input="";kind="";output="";overwrite=0;while(( $# ));do case "$1" in --input)input="$2";shift 2;;--kind)kind="$2";shift 2;;--output)output="$2";shift 2;;--overwrite)overwrite=1;shift;;-h|--help)usage;exit 0;;*)echo "ERROR: unknown argument: $1" >&2;exit 2;;esac;done
[[ -f "$input"&&-f "$REFERENCE_GRID"&&-n "$output" ]]||{ usage;exit 2;};case "$kind" in bold)rmode=Cu;;mask)rmode=NN;;*)echo 'ERROR: --kind must be bold or mask' >&2;exit 2;;esac;[[ "$input" != "$output" ]]||{ echo 'ERROR: input will not be overwritten' >&2;exit 2;};[[ ! -e "$output"||$overwrite -eq 1 ]]||{ echo "ERROR: output exists: $output" >&2;exit 1;};command -v 3dresample>/dev/null||{ echo 'ERROR: 3dresample unavailable' >&2;exit 1;};mkdir -p "$(dirname "$output")";tmp="$(mktemp "$(dirname "$output")/.resample.XXXXXX.nii.gz")";trap 'rm -f -- "$tmp"' EXIT;3dresample -master "$REFERENCE_GRID" -rmode "$rmode" -input "$input" -prefix "$tmp";[[ -s "$tmp" ]]||{ echo 'ERROR: resampling produced no output' >&2;exit 1;};mv -f -- "$tmp" "$output";python3 "$SCRIPT_DIR/check_grid.py" --reference "$REFERENCE_GRID" --image "$output" --json-output "${output%.nii.gz}_grid.json";echo "Wrote RF1-grid $kind: $output"
